use super::authority::parse_authority;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct URL {
    scheme: String,
    authority: String,
    userinfo: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
    had_authority_syntax: bool,
}

impl URL {
    pub fn new(input: &str) -> Self {
        let mut url = Self {
            scheme: String::new(),
            authority: String::new(),
            userinfo: String::new(),
            host: String::new(),
            port: -1,
            path: String::new(),
            query: String::new(),
            fragment: String::new(),
            had_authority_syntax: false,
        };

        if let Some(index) = input.find("://") {
            url.had_authority_syntax = true;

            let scheme = &input[..index];
            if !scheme.is_empty() {
                url.scheme = scheme.to_string();
            }

            let tail = &input[index + 3..];
            let authority_end = tail
                .find(|ch| matches!(ch, '/' | '?' | '#'))
                .unwrap_or(tail.len());
            let parts = parse_authority(&tail[..authority_end]);

            url.userinfo = parts.userinfo;
            url.host = parts.host;
            url.port = parts.port;
            url.authority = parts.authority();
            url.parse_tail(&tail[authority_end..]);
        } else {
            url.parse_tail(input);
        }

        url
    }

    fn parse_tail(&mut self, tail: &str) {
        let query_index = tail.find('?');
        let fragment_index = tail.find('#');

        let path_end = match (query_index, fragment_index) {
            (Some(query), Some(fragment)) => query.min(fragment),
            (Some(query), None) => query,
            (None, Some(fragment)) => fragment,
            (None, None) => tail.len(),
        };

        self.path = tail[..path_end].to_string();

        if let Some(query) = query_index {
            if fragment_index.map_or(true, |fragment| query < fragment) {
                let query_end = fragment_index.unwrap_or(tail.len());
                self.query = tail[query + 1..query_end].to_string();
            }
        }

        if let Some(fragment) = fragment_index {
            self.fragment = tail[fragment + 1..].to_string();
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> &str {
        &self.authority
    }

    pub fn userinfo(&self) -> &str {
        &self.userinfo
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn has_scheme(&self) -> bool {
        !self.scheme.is_empty()
    }

    pub fn has_authority(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_userinfo(&self) -> bool {
        !self.userinfo.is_empty()
    }

    pub fn has_host(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_port(&self) -> bool {
        self.port >= 0
    }

    pub fn has_path(&self) -> bool {
        !self.path.is_empty()
    }

    pub fn has_query(&self) -> bool {
        !self.query.is_empty()
    }

    pub fn has_fragment(&self) -> bool {
        !self.fragment.is_empty()
    }

    pub fn to_string(&self) -> String {
        let mut output = String::new();

        if !self.scheme.is_empty() {
            output.push_str(&self.scheme);
            output.push_str("://");
            output.push_str(&self.authority);
        } else if !self.had_authority_syntax {
            output.push_str(&self.path);
        }

        if self.had_authority_syntax {
            output.push_str(&self.path);
        }

        if !self.query.is_empty() {
            output.push('?');
            output.push_str(&self.query);
        }

        if !self.fragment.is_empty() {
            output.push('#');
            output.push_str(&self.fragment);
        }

        output
    }

    pub fn is_valid(&self) -> bool {
        self.has_host() || self.has_path()
    }
}

#[cfg(test)]
mod tests {
    use super::URL;

    #[test]
    fn parses_full_url() {
        let url = URL::new("http://user:pass@example.com:8080/a/b?c=d#e");

        assert_eq!(url.scheme(), "http");
        assert_eq!(url.authority(), "user:pass@example.com:8080");
        assert_eq!(url.userinfo(), "user:pass");
        assert_eq!(url.host(), "example.com");
        assert_eq!(url.port(), 8080);
        assert_eq!(url.path(), "/a/b");
        assert_eq!(url.query(), "c=d");
        assert_eq!(url.fragment(), "e");
        assert!(url.is_valid());
        assert_eq!(url.to_string(), "http://user:pass@example.com:8080/a/b?c=d#e");
    }

    #[test]
    fn keeps_path_only_inputs_valid() {
        let url = URL::new("foo?bar#baz");

        assert_eq!(url.scheme(), "");
        assert_eq!(url.path(), "foo");
        assert_eq!(url.query(), "bar");
        assert_eq!(url.fragment(), "baz");
        assert!(url.is_valid());
        assert_eq!(url.to_string(), "foo?bar#baz");
    }

    #[test]
    fn drops_authority_from_empty_scheme_serialization() {
        let url = URL::new("://bad/path");

        assert_eq!(url.authority(), "bad");
        assert_eq!(url.host(), "bad");
        assert_eq!(url.path(), "/path");
        assert_eq!(url.to_string(), "/path");
        assert!(url.is_valid());
    }

    #[test]
    fn ignores_non_digit_port_suffixes() {
        let url = URL::new("http://host:123abc/path");

        assert_eq!(url.authority(), "host:123");
        assert_eq!(url.port(), 123);
        assert_eq!(url.to_string(), "http://host:123/path");
    }
}

