#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct AuthorityParts {
    pub(crate) userinfo: String,
    pub(crate) host: String,
    pub(crate) port: i32,
}

impl AuthorityParts {
    pub(crate) fn authority(&self) -> String {
        let mut authority = String::new();

        if !self.userinfo.is_empty() {
            authority.push_str(&self.userinfo);
            authority.push('@');
        }

        authority.push_str(&self.host);

        if self.port >= 0 {
            authority.push(':');
            authority.push_str(&self.port.to_string());
        }

        authority
    }
}

pub(crate) fn parse_authority(raw: &str) -> AuthorityParts {
    let (userinfo, host_port) = match raw.find('@') {
        Some(index) => {
            let candidate = &raw[..index];
            let userinfo = if candidate.is_empty() {
                String::new()
            } else {
                candidate.to_string()
            };
            (userinfo, &raw[index + 1..])
        }
        None => (String::new(), raw),
    };

    let (host, port) = match host_port.find(':') {
        Some(index) => {
            let host = host_port[..index].to_string();
            let digits: String = host_port[index + 1..]
                .chars()
                .take_while(|ch| ch.is_ascii_digit())
                .collect();
            let port = if digits.is_empty() {
                -1
            } else {
                digits.parse::<i32>().unwrap_or(-1)
            };
            (host, port)
        }
        None => (host_port.to_string(), -1),
    };

    AuthorityParts {
        userinfo,
        host,
        port,
    }
}

